#!/bin/bash
perl -i -0777 -pe 's/(            \} else \{\n)(.*?)(                if \(generatedPin != null\) \{)/$1                OutlinedTextField(\n                    value = myName,\n                    onValueChange = { myName = it },\n                    label = { Text("Nama Anda (Cth: Suami \/ Istri)") },\n                    modifier = Modifier.fillMaxWidth(),\n                    shape = RoundedCornerShape(16.dp),\n                    singleLine = true,\n                    colors = OutlinedTextFieldDefaults.colors(\n                        focusedBorderColor = IndigoPrimary,\n                        cursorColor = IndigoPrimary\n                    )\n                )\n                Spacer(modifier = Modifier.height(24.dp))\n                Text(\n                    text = "Hubungkan akun Anda dengan menggunakan PIN unik untuk mulai mencatat keuangan bersama.",\n                    fontSize = 15.sp,\n                    textAlign = TextAlign.Center,\n                    color = MaterialTheme.colorScheme.onSurfaceVariant,\n                    modifier = Modifier.padding(bottom = 32.dp)\n                )\n$3/s' app/src/main/java/com/example/ui/screens/PinConnectScreen.kt
